-- composition of rule kernels BloomFilter x OrderBySubq (sqlite), template product
CREATE VIEW n1 AS SELECT 7 AS c0 UNION SELECT 1 AS c0;
SELECT count(*) FROM (WITH cte1 AS MATERIALIZED (SELECT MIN (CAST('abc' AS TEXT), CAST('ß' AS TEXT)) AS c0 FROM (SELECT FORMAT ('%s|%s', '{"k": 1, "a": [1, 2]}', '{}') AS c0, '2000-01-01 00:00:00' AS c1 FROM n1 AS a1 GROUP BY a1.c0) AS a2 WHERE TRUE GROUP BY a2.c1) SELECT 7 AS c0, (-42) AS c1, CAST(100 AS INTEGER) AS c2 FROM cte1 AS a3 WHERE FALSE) AS ka CROSS JOIN (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, CAST('a' AS TEXT) AS c1 UNION ALL SELECT ('2000-01-01 00:00:00' IN (SELECT '1970-01-01 00:00:00' AS c0)) AS c0, CAST('%' AS TEXT) AS c1 FROM rc AS a1) AS kb;
-- pgfuzz:check kernel:product SELECT (SELECT count(*) FROM (WITH cte1 AS MATERIALIZED (SELECT MIN (CAST('abc' AS TEXT), CAST('ß' AS TEXT)) AS c0 FROM (SELECT FORMAT ('%s|%s', '{"k": 1, "a": [1, 2]}', '{}') AS c0, '2000-01-01 00:00:00' AS c1 FROM n1 AS a1 GROUP BY a1.c0) AS a2 WHERE TRUE GROUP BY a2.c1) SELECT 7 AS c0, (-42) AS c1, CAST(100 AS INTEGER) AS c2 FROM cte1 AS a3 WHERE FALSE) AS ka) * (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, CAST('a' AS TEXT) AS c1 UNION ALL SELECT ('2000-01-01 00:00:00' IN (SELECT '1970-01-01 00:00:00' AS c0)) AS c0, CAST('%' AS TEXT) AS c1 FROM rc AS a1) AS kb)
